CREATE OR REPLACE FUNCTION public.validar_acao_educativa() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status NOT IN ('AGENDADA','EM_ANDAMENTO','REALIZADA','CANCELADA') THEN RAISE EXCEPTION 'Situação inválida para ação educativa'; END IF; IF NOT EXISTS (SELECT 1 FROM public.categorias_educativas WHERE id=NEW.categoria AND (ativo OR (TG_OP='UPDATE' AND NEW.categoria=OLD.categoria))) THEN RAISE EXCEPTION 'Selecione uma categoria ativa para a ação educativa'; END IF; IF NEW.horario_inicio IS NOT NULL AND NEW.horario_fim IS NOT NULL AND NEW.horario_fim <= NEW.horario_inicio THEN RAISE EXCEPTION 'O horário final deve ser posterior ao horário inicial'; END IF; RETURN NEW; END $$;